insert into public.bible_verses (id, book_key, book_name, chapter, verse, content, sort_order)
values
('isa-42-20','isa','이사야',42,20,'네가 많은 것을 볼지라도 유의하지 아니하며 귀가 열려 있을지라도 듣지 아니하는도다',18501),
('isa-42-21','isa','이사야',42,21,'여호와께서 그의 의로 말미암아 기쁨으로 교훈을 크게 하며 존귀하게 하려 하셨으나',18502),
('isa-42-22','isa','이사야',42,22,'이 백성이 도둑 맞으며 탈취를 당하며 다 굴 속에 잡히며 옥에 갇히도다 노략을 당하되 구할 자가 없고 탈취를 당하되 되돌려 주라 말할 자가 없도다',18503),
('isa-42-23','isa','이사야',42,23,'너희 중에 누가 이 일에 귀를 기울이겠느냐 누가 뒤에 올 일을 삼가 듣겠느냐',18504),
('isa-42-24','isa','이사야',42,24,'야곱이 탈취를 당하게 하신 자가 누구냐 이스라엘을 약탈자들에게 넘기신 자가 누구냐 여호와가 아니시냐 우리가 그에게 범죄하였도다 그들이 그의 길로 다니기를 원하지 아니하며 그의 교훈을 순종하지 아니하였도다',18505),
('isa-42-25','isa','이사야',42,25,'그러므로 여호와께서 맹렬한 진노와 전쟁의 위력을 이스라엘에게 쏟아 부으시매 그 사방에서 불타오르나 깨닫지 못하며 몸이 타나 마음에 두지 아니하는도다',18506),
('isa-43-1','isa','이사야',43,1,'야곱아 너를 창조하신 여호와께서 지금 말씀하시느니라 이스라엘아 너를 지으신 이가 말씀하시느니라 너는 두려워하지 말라 내가 너를 구속하였고 내가 너를 지명하여 불렀나니 너는 내 것이라',18507),
('isa-43-2','isa','이사야',43,2,'네가 물 가운데로 지날 때에 내가 너와 함께 할 것이라 강을 건널 때에 물이 너를 침몰하지 못할 것이며 네가 불 가운데로 지날 때에 타지도 아니할 것이요 불꽃이 너를 사르지도 못하리니',18508),
('isa-43-3','isa','이사야',43,3,'대저 나는 여호와 네 하나님이요 이스라엘의 거룩한 이요 네 구원자임이라 내가 애굽을 너의 속량물로, 구스와 스바를 너를 대신하여 주었노라',18509),
('isa-43-4','isa','이사야',43,4,'네가 내 눈에 보배롭고 존귀하며 내가 너를 사랑하였은즉 내가 네 대신 사람들을 내어 주며 백성들이 네 생명을 대신하리니',18510),
('isa-43-5','isa','이사야',43,5,'두려워하지 말라 내가 너와 함께 하여 네 자손을 동쪽에서부터 오게 하며 서쪽에서부터 너를 모을 것이며',18511),
('isa-43-6','isa','이사야',43,6,'내가 북쪽에게 이르기를 내놓으라 남쪽에게 이르기를 가두어 두지 말라 내 아들들을 먼 곳에서 이끌며 내 딸들을 땅 끝에서 오게 하며',18512),
('isa-43-7','isa','이사야',43,7,'내 이름으로 불려지는 모든 자 곧 내가 내 영광을 위하여 창조한 자를 오게 하라 그를 내가 지었고 그를 내가 만들었느니라',18513),
('isa-43-8','isa','이사야',43,8,'눈이 있어도 보지 못하고 귀가 있어도 듣지 못하는 백성을 이끌어 내라',18514),
('isa-43-9','isa','이사야',43,9,'열방은 모였으며 민족들이 회집하였는데 그들 중에 누가 이 일을 알려 주며 이전 일들을 우리에게 들려 주겠느냐 그들이 그들의 증인을 세워서 자기들의 옳음을 나타내고 듣는 자들이 옳다고 말하게 하여 보라',18515),
('isa-43-10','isa','이사야',43,10,'나 여호와가 말하노라 너희는 나의 증인, 나의 종으로 택함을 입었나니 이는 너희가 나를 알고 믿으며 내가 그인 줄 깨닫게 하려 함이라 나의 전에 지음을 받은 신이 없었느니라 나의 후에도 없으리라',18516),
('isa-43-11','isa','이사야',43,11,'나 곧 나는 여호와라 나 외에 구원자가 없느니라',18517),
('isa-43-12','isa','이사야',43,12,'내가 알려 주었으며 구원하였으며 보였고 너희 중에 다른 신이 없었나니 그러므로 너희는 나의 증인이요 나는 하나님이니라 여호와의 말씀이니라',18518),
('isa-43-13','isa','이사야',43,13,'과연 태초로부터 나는 그이니 내 손에서 건질 자가 없도다 내가 행하리니 누가 막으리요',18519),
('isa-43-14','isa','이사야',43,14,'너희의 구속자요 이스라엘의 거룩한 이 여호와가 말하노라 너희를 위하여 내가 바벨론에 사람을 보내어 모든 갈대아 사람에게 자기들이 연락하던 배를 타고 도망하여 내려가게 하리라',18520),
('isa-43-15','isa','이사야',43,15,'나는 여호와 너희의 거룩한 이요 이스라엘의 창조자요 너희의 왕이니라',18521),
('isa-43-16','isa','이사야',43,16,'나 여호와가 이같이 말하노라 바다 가운데에 길을, 큰 물 가운데에 지름길을 내고',18522),
('isa-43-17','isa','이사야',43,17,'병거와 말과 군대의 용사를 이끌어 내어 그들이 일시에 엎드러져 일어나지 못하고 소멸하기를 꺼져가는 등불 같게 하였느니라',18523),
('isa-43-18','isa','이사야',43,18,'너희는 이전 일을 기억하지 말며 옛날 일을 생각하지 말라',18524),
('isa-43-19','isa','이사야',43,19,'보라 내가 새 일을 행하리니 이제 나타낼 것이라 너희가 그것을 알지 못하겠느냐 반드시 내가 광야에 길을 사막에 강을 내리니',18525),
('isa-43-20','isa','이사야',43,20,'장차 들짐승 곧 승냥이와 타조도 나를 존경할 것은 내가 광야에 물을, 사막에 강들을 내어 내 백성, 내가 택한 자에게 마시게 할 것임이라',18526),
('isa-43-21','isa','이사야',43,21,'이 백성은 내가 나를 위하여 지었나니 나를 찬송하게 하려 함이니라',18527),
('isa-43-22','isa','이사야',43,22,'그러나 야곱아 너는 나를 부르지 아니하였고 이스라엘아 너는 나를 괴롭게 여겼으며',18528),
('isa-43-23','isa','이사야',43,23,'네 번제의 양을 내게로 가져오지 아니하였고 네 제물로 나를 공경하지 아니하였느니라 나는 제물로 말미암아 너를 수고롭게 하지 아니하였고 유향으로 말미암아 너를 괴롭게 하지 아니하였거늘',18529),
('isa-43-24','isa','이사야',43,24,'너는 나를 위하여 돈으로 향품을 사지 아니하며 희생의 기름으로 나를 흡족하게 하지 아니하고 네 죄짐으로 나를 수고롭게 하며 네 죄악으로 나를 괴롭게 하였느니라',18530),
('isa-43-25','isa','이사야',43,25,'나 곧 나는 나를 위하여 네 허물을 도말하는 자니 네 죄를 기억하지 아니하리라',18531),
('isa-43-26','isa','이사야',43,26,'너는 나에게 기억이 나게 하라 우리가 함께 변론하자 너는 말하여 네가 의로움을 나타내라',18532),
('isa-43-27','isa','이사야',43,27,'네 시조가 범죄하였고 너의 교사들이 나를 배반하였나니',18533),
('isa-43-28','isa','이사야',43,28,'그러므로 내가 성소의 어른들에게 욕되게 하며 야곱이 진멸 당하도록 내어 주며 이스라엘이 비방 거리가 되게 하리라',18534),
('isa-44-1','isa','이사야',44,1,'나의 종 야곱, 내가 택한 이스라엘아 이제 들으라',18535),
('isa-44-2','isa','이사야',44,2,'너를 만들고 너를 모태에서부터 지어 낸 너를 도와 줄 여호와가 이같이 말하노라 나의 종 야곱, 내가 택한 여수룬아 두려워하지 말라',18536),
('isa-44-3','isa','이사야',44,3,'나는 목마른 자에게 물을 주며 마른 땅에 시내가 흐르게 하며 나의 영을 네 자손에게, 나의 복을 네 후손에게 부어 주리니',18537),
('isa-44-4','isa','이사야',44,4,'그들이 풀 가운데에서 솟아나기를 시냇가의 버들 같이 할 것이라',18538),
('isa-44-5','isa','이사야',44,5,'한 사람은 이르기를 나는 여호와께 속하였다 할 것이며 또 한 사람은 야곱의 이름으로 자기를 부를 것이며 또 다른 사람은 자기가 여호와께 속하였음을 그의 손으로 기록하고 이스라엘의 이름으로 존귀히 여김을 받으리라',18539),
('isa-44-6','isa','이사야',44,6,'이스라엘의 왕인 여호와, 이스라엘의 구원자인 만군의 여호와가 이같이 말하노라 나는 처음이요 나는 마지막이라 나 외에 다른 신이 없느니라',18540),
('isa-44-7','isa','이사야',44,7,'내가 영원한 백성을 세운 이후로 나처럼 외치며 알리며 나에게 설명할 자가 누구냐 있거든 될 일과 장차 올 일을 그들에게 알릴지어다',18541),
('isa-44-8','isa','이사야',44,8,'너희는 두려워하지 말며 겁내지 말라 내가 예로부터 너희에게 듣게 하지 아니하였느냐 알리지 아니하였느냐 너희는 나의 증인이라 나 외에 신이 있겠느냐 과연 반석은 없나니 다른 신이 있음을 내가 알지 못하노라',18542),
('isa-44-9','isa','이사야',44,9,'우상을 만드는 자는 다 허망하도다 그들이 원하는 것들은 무익한 것이거늘 그것들의 증인들은 보지도 못하며 알지도 못하니 그러므로 수치를 당하리라',18543),
('isa-44-10','isa','이사야',44,10,'신상을 만들며 무익한 우상을 부어 만든 자가 누구냐',18544),
('isa-44-11','isa','이사야',44,11,'보라 그와 같은 무리들이 다 수치를 당할 것이라 그 대장장이들은 사람일 뿐이라 그들이 다 모여 서서 두려워하며 함께 수치를 당할 것이니라',18545),
('isa-44-12','isa','이사야',44,12,'철공은 철로 연장을 만들고 숯불로 일하며 망치를 가지고 그것을 만들며 그의 힘센 팔로 그 일을 하나 배가 고프면 기운이 없고 물을 마시지 아니하면 피로하니라',18546),
('isa-44-13','isa','이사야',44,13,'목공은 줄을 늘여 재고 붓으로 긋고 대패로 밀고 곡선자로 그어 사람의 아름다움을 따라 사람의 모양을 만들어 집에 두게 하며',18547),
('isa-44-14','isa','이사야',44,14,'그는 자기를 위하여 백향목을 베며 디르사 나무와 상수리나무를 취하며 숲의 나무들 가운데에서 자기를 위하여 한 나무를 정하며 나무를 심고 비를 맞고 자라게도 하느니라',18548),
('isa-44-15','isa','이사야',44,15,'이 나무는 사람이 땔감을 삼는 것이거늘 그가 그것을 가지고 자기 몸을 덥게도 하고 불을 피워 떡을 굽기도 하고 신상을 만들어 경배하며 우상을 만들고 그 앞에 엎드리기도 하는구나',18549),
('isa-44-16','isa','이사야',44,16,'그 중의 절반은 불에 사르고 그 절반으로는 고기를 구워 먹고 배불리며 또 몸을 덥게 하여 이르기를 아하 따뜻하다 내가 불을 보았구나 하면서',18550),
('isa-44-17','isa','이사야',44,17,'그 나머지로 신상 곧 자기의 우상을 만들고 그 앞에 엎드려 경배하며 그것에게 기도하여 이르기를 너는 나의 신이니 나를 구원하라 하는도다',18551),
('isa-44-18','isa','이사야',44,18,'그들이 알지도 못하고 깨닫지도 못함은 그들의 눈이 가려서 보지 못하며 그들의 마음이 어두워져서 깨닫지 못함이니라',18552),
('isa-44-19','isa','이사야',44,19,'마음에 생각도 없고 지식도 없고 총명도 없으므로 내가 그것의 절반을 불 사르고 또한 그 숯불 위에서 떡도 굽고 고기도 구워 먹었거늘 내가 어찌 그 나머지로 가증한 물건을 만들겠으며 내가 어찌 그 나무 토막 앞에 굴복하리요 말하지 아니하니',18553),
('isa-44-20','isa','이사야',44,20,'그는 재를 먹고 허탄한 마음에 미혹되어 자기의 영혼을 구원하지 못하며 나의 오른손에 거짓 것이 있지 아니하냐 하지도 못하느니라',18554),
('isa-44-21','isa','이사야',44,21,'야곱아 이스라엘아 이 일을 기억하라 너는 내 종이니라 내가 너를 지었으니 너는 내 종이니라 이스라엘아 너는 나에게 잊혀지지 아니하리라',18555),
('isa-44-22','isa','이사야',44,22,'내가 네 허물을 빽빽한 구름 같이, 네 죄를 안개 같이 없이하였으니 너는 내게로 돌아오라 내가 너를 구속하였음이니라',18556),
('isa-44-23','isa','이사야',44,23,'여호와께서 이 일을 행하셨으니 하늘아 노래할지어다 땅의 깊은 곳들아 높이 부를지어다 산들아 숲과 그 가운데의 모든 나무들아 소리내어 노래할지어다 여호와께서 야곱을 구속하셨으니 이스라엘 중에 자기의 영광을 나타내실 것임이로다',18557),
('isa-44-24','isa','이사야',44,24,'네 구속자요 모태에서 너를 지은 나 여호와가 이같이 말하노라 나는 만물을 지은 여호와라 홀로 하늘을 폈으며 나와 함께 한 자 없이 땅을 펼쳤고',18558),
('isa-44-25','isa','이사야',44,25,'헛된 말을 하는 자들의 징표를 폐하며 점 치는 자들을 미치게 하며 지혜로운 자들을 물리쳐 그들의 지식을 어리석게 하며',18559),
('isa-44-26','isa','이사야',44,26,'그의 종의 말을 세워 주며 그의 사자들의 계획을 성취하게 하며 예루살렘에 대하여는 이르기를 거기에 사람이 살리라 하며 유다 성읍들에 대하여는 중건될 것이라 내가 그 황폐한 곳들을 복구시키리라 하며',18560),
('isa-44-27','isa','이사야',44,27,'깊음에 대하여는 이르기를 마르라 내가 네 강물들을 마르게 하리라 하며',18561),
